#import <Foundation/Foundation.h>
#import <PDFKit/PDFKit.h>
#import <AppKit/AppKit.h>
int main(int argc, char *argv[]) { @autoreleasepool { for(int i=1;i<argc;i++){ PDFDocument *doc=[[PDFDocument alloc]initWithURL:[NSURL fileURLWithPath:@(argv[i])]]; NSMutableString *text=[NSMutableString stringWithFormat:@"Pages: %lu\n",(unsigned long)doc.pageCount]; for(NSUInteger n=0;n<doc.pageCount;n++){ [text appendFormat:@"\n--- PAGE %lu ---\n%@",(unsigned long)n+1,[[doc pageAtIndex:n]string]]; } [text writeToFile:[NSString stringWithFormat:@"smart-report-studio/docs/source-%d.txt",i] atomically:YES encoding:NSUTF8StringEncoding error:nil]; for(NSNumber *n in @[@0,@7,@8,@20]) { PDFPage *page=[doc pageAtIndex:n.unsignedIntegerValue]; NSImage *img=[page thumbnailOfSize:NSMakeSize(1000,1414) forBox:kPDFDisplayBoxMediaBox]; NSBitmapImageRep *rep=[[NSBitmapImageRep alloc]initWithData:img.TIFFRepresentation]; [[rep representationUsingType:NSBitmapImageFileTypePNG properties:@{}]writeToFile:[NSString stringWithFormat:@"smart-report-studio/docs/source-%d-page-%lu.png",i,n.unsignedIntegerValue+1] atomically:YES]; } NSLog(@"Source %d: %lu pages",i,(unsigned long)doc.pageCount); } } return 0; }
